// ─── Data types ───────────────────────────────────────────────────────────────

export interface QuoteResult {
  symbol: string;
  shortName: string;
  price: number;
  change: number;
  changePct: number;
  open: number;
  high: number;
  low: number;
  prevClose: number;
  week52High: number;
  week52Low: number;
  marketState: string;
}

export interface DayBar {
  date: string;       // YYYY-MM-DD
  open: number;
  high: number;
  low: number;
  close: number;
  changePct: number;  // vs previous close
}

// ─── API config ───────────────────────────────────────────────────────────────
// Get a free key at https://financialmodelingprep.com/register
// Free tier: 250 req/day — enough at 30-min refresh intervals.

export const FMP_API_KEY = process.env.FMP_API_KEY as string;

const FMP = 'https://financialmodelingprep.com/stable';

// ─── Financial Modeling Prep helpers ─────────────────────────────────────────
// Free tier: one symbol per request. We stagger calls 300 ms apart to avoid
// 429s. Refresh every 4 hours keeps usage ~168 req/day (under the 250 limit).

async function fetchSingleQuote(symbol: string): Promise<QuoteResult | null> {
  try {
    const res = await fetch(`${FMP}/quote?symbol=${encodeURIComponent(symbol)}&apikey=${FMP_API_KEY}`);
    if (!res.ok) return null;
    const json: Record<string, unknown>[] = await res.json();
    const q = Array.isArray(json) ? json[0] : null;
    if (!q) return null;
    const price     = (q.price ?? 0) as number;
    const prevClose = (q.previousClose ?? price) as number;
    return {
      symbol,
      shortName:   (q.name ?? symbol) as string,
      price,
      change:      (q.change ?? price - prevClose) as number,
      changePct:   (q.changesPercentage ?? 0) as number,
      open:        (q.open    ?? price) as number,
      high:        (q.dayHigh ?? price) as number,
      low:         (q.dayLow  ?? price) as number,
      prevClose,
      week52High:  (q.yearHigh ?? price) as number,
      week52Low:   (q.yearLow  ?? price) as number,
      marketState: 'REGULAR',
    };
  } catch {
    return null;
  }
}

async function fetchQuotes(symbols: string[]): Promise<Map<string, QuoteResult>> {
  const map = new Map<string, QuoteResult>();
  for (let i = 0; i < symbols.length; i++) {
    if (i > 0) await new Promise((r) => setTimeout(r, 300));
    const q = await fetchSingleQuote(symbols[i]);
    if (q) map.set(symbols[i], q);
  }
  return map;
}

function rangeToFrom(range: '5d' | '1mo' | '3mo'): string {
  const now  = new Date();
  const from = new Date(now);
  if (range === '5d')  from.setDate(now.getDate() - 7);
  if (range === '1mo') from.setMonth(now.getMonth() - 1);
  if (range === '3mo') from.setMonth(now.getMonth() - 3);
  return from.toISOString().slice(0, 10);
}

async function fetchHistory(symbol: string, range: '5d' | '1mo' | '3mo'): Promise<DayBar[]> {
  const from = rangeToFrom(range);
  const to   = new Date().toISOString().slice(0, 10);
  const res  = await fetch(
    `${FMP}/historical-price-eod/full?symbol=${encodeURIComponent(symbol)}&from=${from}&to=${to}&apikey=${FMP_API_KEY}`,
  );
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const json = await res.json();
  const historical: Record<string, unknown>[] = json?.historical ?? [];

  // FMP returns newest-first — reverse to chronological
  return historical
    .slice()
    .reverse()
    .map((d, i, arr) => {
      const close    = (d.close ?? 0) as number;
      const prevClose = i > 0 ? (arr[i - 1].close as number ?? close) : close;
      return {
        date:      d.date as string,
        open:      (d.open  ?? close) as number,
        high:      (d.high  ?? close) as number,
        low:       (d.low   ?? close) as number,
        close,
        changePct: (d.changePercent ?? (prevClose !== 0 ? ((close - prevClose) / prevClose) * 100 : 0)) as number,
      };
    });
}

// ─── Hooks ────────────────────────────────────────────────────────────────────

export function useQuotes(symbols: string[], refreshMs = 30000) {
  const [quotes, setQuotes]   = useState<Map<string, QuoteResult>>(new Map());
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState<string | null>(null);

  const load = useCallback(async () => {
    try {
      const map = await fetchQuotes(symbols);
      setQuotes(map);
      setError(null);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Fetch failed');
    } finally {
      setLoading(false);
    }
  }, [symbols.join(',')]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    load();
    const id = setInterval(load, refreshMs);
    return () => clearInterval(id);
  }, [load, refreshMs]);

  return { quotes, loading, error };
}

export function useHistory(symbol: string, range: '5d' | '1mo' | '3mo') {
  const [bars, setBars]       = useState<DayBar[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState<string | null>(null);

  const load = useCallback(async () => {
    try {
      const data = await fetchHistory(symbol, range);
      setBars(data);
      setError(null);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Fetch failed');
    } finally {
      setLoading(false);
    }
  }, [symbol, range]);

  useEffect(() => {
    load();
  }, [load]);

  return { bars, loading, error };
}

// ─── Colour helpers ───────────────────────────────────────────────────────────

export function pctColor(pct: number): string {
  if (pct > 0) return '#3fb950';
  if (pct < 0) return '#f85149';
  return '#8b949e';
}

export function heatColor(pct: number): string {
  // Maps pct change to a background colour for the heatmap cells
  const clamped = Math.max(-4, Math.min(4, pct));
  if (clamped === 0) return '#21262d';
  if (clamped > 0) {
    const t = clamped / 4;
    const g = Math.round(80 + t * 105);
    const r = Math.round(20 + t * 10);
    const b = Math.round(30 + t * 10);
    return `rgb(${r},${g},${b})`;
  }
  const t = (-clamped) / 4;
  const r = Math.round(100 + t * 148);
  const g = Math.round(20 + t * 10);
  const b = Math.round(20 + t * 10);
  return `rgb(${r},${g},${b})`;
}

export function fmt(n: number, decimals = 2): string {
  return n.toLocaleString('en-US', { minimumFractionDigits: decimals, maximumFractionDigits: decimals });
}

export function fmtPct(n: number): string {
  return `${n >= 0 ? '+' : ''}${n.toFixed(2)}%`;
}
